var maximumSubsequenceCount = function(text, pattern) {
    const p0 = pattern[0], p1 = pattern[1];
    let base = 0;
    let c0 = 0, c1 = 0;
    for (const ch of text) {
        if (ch === p1) {
            base += c0;
            c1++;
        }
        if (ch === p0) {
            c0++;
        }
    }
    return base + Math.max(c0, c1);
};
